<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/auth.php'; require_once dirname(__DIR__) . '/includes/csrf.php'; require_once __DIR__ . '/layout.php'; require_once dirname(__DIR__) . '/services/billing.php';
$current=tuman_require_role('TEACHER'); $id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); if(!$id){http_response_code(404);exit('Billing unavailable.');}$record=tuman_teacher_billing_rule(tuman_database(),$current['id'],(int)$id);if($record===null){http_response_code(404);exit('Billing unavailable.');}$error=null;$values=['rule_name'=>$record['rule_name']??('Rule #'.$record['id']),'billing_mode'=>$record['billing_mode'],'rate'=>$record['rate'],'currency_code'=>$record['currency_code']??'INR','effective_from'=>$record['effective_from'],'effective_to'=>$record['effective_to']??''];
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($values as $key=>$value){$values[$key]=trim((string)($_POST[$key]??''));}if(!tuman_csrf_is_valid($_POST['csrf_token']??null)){$error='Your request could not be verified. Please try again.';}else{try{tuman_update_billing_rule(tuman_database(),$current['id'],(int)$id,$values);header('Location: /Tuman/teacher/billing.php?updated=1');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to update the billing rule right now.';}}}
tuman_teacher_page_start('Edit billing rule');
