<h1>Edit billing rule</h1><p>Changes do not alter existing invoices or payments.</p><?php if($error): ?><p role="alert"><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><p><label>Rule name <input name="rule_name" maxlength="100" required value="<?= htmlspecialchars($values['rule_name'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Billing mode <select name="billing_mode"><?php foreach(TUMAN_BILLING_MODES as $mode): ?><option value="<?= $mode ?>"<?= $mode===$values['billing_mode']?' selected':'' ?>><?= $mode==='HOURLY'?'Hourly':'Fixed monthly' ?></option><?php endforeach; ?></select></label></p><p><label>Currency <select name="currency_code"><?php foreach(TUMAN_CURRENCIES as $code=>$name): ?><option value="<?= $code ?>"<?= $code===$values['currency_code']?' selected':'' ?>><?= htmlspecialchars($code.' — '.$name,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><label>Rate <input name="rate" required value="<?= htmlspecialchars($values['rate'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Effective from <input type="date" name="effective_from" required value="<?= htmlspecialchars($values['effective_from'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Effective to <input type="date" name="effective_to" value="<?= htmlspecialchars($values['effective_to'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><button>Save changes</button> <a href="/Tuman/teacher/billing.php">Cancel</a></p></form>
